// Normalize Payload
// Turns Meta's webhook envelope into one flat item per incoming message.
// Status updates (sent / delivered / read) and reactions produce no items,
// so the execution simply ends there.
const guessLang = (text) => {
  const s = ' ' + String(text || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z\s]/g, ' ') + ' ';
  const score = (words) => words.reduce((n, w) => n + (s.includes(' ' + w + ' ') ? 1 : 0), 0);
  const es = score(['hola', 'buenas', 'que', 'como', 'cual', 'cuanto', 'cuesta', 'precio', 'horario', 'abren', 'tienen', 'quiero', 'necesito', 'gracias', 'por', 'favor', 'donde', 'cuando', 'hay', 'una', 'los', 'las', 'del']);
  const pt = score(['ola', 'oi', 'bom', 'boa', 'voce', 'voces', 'quanto', 'custa', 'quais', 'obrigado', 'obrigada', 'preciso', 'quero', 'onde', 'tem', 'nao', 'sim', 'uma', 'dos', 'das']);
  const en = score(['hello', 'hi', 'what', 'how', 'much', 'do', 'you', 'have', 'the', 'is', 'are', 'open', 'price', 'thanks', 'thank', 'please', 'want', 'need', 'where', 'when', 'can', 'order']);
  if (pt > es && pt >= en) return 'pt';
  if (es > en && es >= pt) return 'es';
  return 'en';
};

const out = [];
for (const item of $input.all()) {
  const body = item.json.body || {};
  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      const value = change.value || {};
      const names = {};
      for (const c of value.contacts || []) names[c.wa_id] = (c.profile && c.profile.name) || null;
      for (const m of value.messages || []) {
        if (m.type === 'reaction' || m.type === 'system') continue;
        let text = null;
        if (m.type === 'text') text = m.text && m.text.body;
        else if (m.type === 'button') text = m.button && m.button.text;
        else if (m.type === 'interactive') {
          const i = m.interactive || {};
          text = (i.button_reply && i.button_reply.title) || (i.list_reply && i.list_reply.title);
        }
        text = typeof text === 'string' ? text.trim().slice(0, 1000) : '';
        out.push({
          json: {
            messageId: m.id || null,
            from: m.from,
            name: names[m.from] || null,
            type: text ? 'text' : (m.type && m.type !== 'text' ? m.type : 'unsupported'),
            text,
            timestamp: Number(m.timestamp) || null,
            phoneNumberId: (value.metadata && value.metadata.phone_number_id) || null,
            lang: guessLang(text),
          },
        });
      }
    }
  }
}
return out;

// Deduplicate Messages
// Meta can deliver the same webhook more than once. Remember message ids in
// workflow static data (kept 24 h, max 2000) and drop repeats.
// Note: static data is only saved by ACTIVE workflows, not by manual test runs.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
const TTL_MS = 24 * 60 * 60 * 1000;
const MAX_IDS = 2000;

for (const [id, ts] of Object.entries(store.seen)) {
  if (now - ts > TTL_MS) delete store.seen[id];
}

const fresh = [];
for (const item of $input.all()) {
  const id = item.json.messageId;
  if (id && store.seen[id]) continue;
  if (id) store.seen[id] = now;
  fresh.push(item);
}

const ids = Object.keys(store.seen);
if (ids.length > MAX_IDS) {
  ids.sort((a, b) => store.seen[a] - store.seen[b]);
  for (const id of ids.slice(0, ids.length - MAX_IDS)) delete store.seen[id];
}
return fresh;

// Prepare Unsupported Reply
// Audio, images, stickers, locations... are not read by this starter.
// Answer politely instead of staying silent.
return {
  json: {
    ...$json,
    reply: 'Hi! For now I can only read text messages. Could you type your question?\n\n¡Hola! Por ahora solo puedo leer mensajes de texto. ¿Podrías escribir tu consulta?',
    kind: 'unsupported',
    handoff: false,
    handoffReason: null,
  },
};

// Detect Handoff Keywords
// Cheap first check, before spending an LLM call: does the customer ask for a
// person or sound like a complaint? Patterns run on lowercase text without
// accents. Edit the lists to fit your business and languages.
const PATTERNS = [
  // Spanish
  'hablar con (una |un )?(persona|humano|asesor|agente|operador|encargad[oa]|duen[oa]|alguien)',
  'comunicarme con (una |un )?(persona|humano|asesor|alguien)',
  'persona real',
  'atencion humana',
  '\\b(reclamo|queja|denuncia|estafa|reembolso|devolucion)\\b',
  // English
  '(talk|speak) (to|with) (a |an )?(human|person|agent|representative|someone|manager|owner)',
  'real person',
  'human agent',
  '\\b(complaint|complain|refund|lawsuit|scam)\\b',
  // Portuguese
  'falar com (uma |um )?(pessoa|humano|atendente|gerente|alguem|dono|dona)',
  'atendente humano',
  '\\b(reclamacao|reclamar|reembolso|estorno|golpe)\\b',
];
const text = String($json.text || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const hit = PATTERNS.find((p) => new RegExp(p).test(text));
return {
  json: {
    ...$json,
    handoff: Boolean(hit),
    handoffReason: hit ? 'keyword' : null,
  },
};

// Build LLM Messages
// Combines the system prompt, the business knowledge base, the last N messages
// of this phone number (short-term memory) and the new customer message.
// Memory lives in workflow static data: { memory: { "<number>": [{role, content, ts}] } }
const store = $getWorkflowStaticData('global');
const parsed = parseInt($env.MEMORY_MESSAGES, 10);
const keep = Number.isFinite(parsed) ? Math.max(0, parsed) : 10;
const TTL_MS = 24 * 60 * 60 * 1000; // WhatsApp's customer-service window
const now = Date.now();

const { systemPrompt, knowledge, ...base } = $json;
const past = ((store.memory && store.memory[base.from]) || []).filter((m) => now - m.ts < TTL_MS);
const history = keep ? past.slice(-keep).map(({ role, content }) => ({ role, content })) : [];

const who = base.name ? '\nThe customer\'s WhatsApp profile name is "' + base.name + '" (not verified).' : '';
const systemMessage = systemPrompt + '\n\n=== BUSINESS INFORMATION ===\n' + knowledge + '\n=== END OF BUSINESS INFORMATION ===' + who;
const chatMessages = [...history, { role: 'user', content: base.text }];

return {
  json: {
    ...base,
    systemMessage,
    chatMessages, // without the system message (Anthropic Messages API wants it separately)
    messages: [{ role: 'system', content: systemMessage }, ...chatMessages], // OpenAI-compatible
  },
};

// Parse LLM Reply
// Understands OpenAI-compatible responses (choices[0].message.content) and the
// Anthropic Messages API (content[0].text). If the model answers with the
// [[HANDOFF]] marker, the customer is handed to a person.
const MARKER = '[[HANDOFF]]';
const ctx = $('Build LLM Messages').item.json;
const r = $json;

let raw = '';
if (r.choices && r.choices[0] && r.choices[0].message) raw = r.choices[0].message.content;
else if (Array.isArray(r.content)) raw = r.content.map((p) => p.text || '').join('');
if (Array.isArray(raw)) raw = raw.map((p) => p.text || '').join('');
raw = String(raw || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();

const { messages, systemMessage, chatMessages, ...base } = ctx;
const marked = raw.includes(MARKER);
const empty = raw.length === 0;
const reply = raw.split(MARKER).join('').trim();

return {
  json: {
    ...base,
    reply,
    handoff: marked || empty,
    handoffReason: marked ? 'llm_marker' : (empty ? 'empty_llm_reply' : null),
    kind: marked || empty ? 'handoff' : 'bot',
    model: r.model || null,
    tokens: (r.usage && (r.usage.total_tokens || ((r.usage.input_tokens || 0) + (r.usage.output_tokens || 0)))) || null,
  },
};

// LLM Error Fallback
// Reached only when the LLM call still fails after 3 attempts. Instead of
// leaving the customer without an answer, hand the chat to a person.
const ctx = $('Build LLM Messages').item.json;
const { messages, systemMessage, chatMessages, ...base } = ctx;
const err = ($json.error && ($json.error.message || $json.error.description)) || $json.message || 'LLM request failed';
return {
  json: {
    ...base,
    reply: '',
    handoff: true,
    handoffReason: 'llm_error',
    kind: 'handoff',
    error: String(err).slice(0, 300),
  },
};

// Prepare Handoff Reply
// Message for the customer (the LLM's own sentence if it wrote one, otherwise a
// fixed text in the customer's language) plus a ready-made note for the owner.
const FIXED = {
  en: 'Thanks for your message. A member of our team will contact you shortly.',
  es: 'Gracias por tu mensaje. Una persona de nuestro equipo se pondrá en contacto contigo en breve.',
  pt: 'Obrigado pela sua mensagem. Uma pessoa da nossa equipe entrará em contato em breve.',
};
const reply = String($json.reply || '').trim() || FIXED[$json.lang] || FIXED.en;
const ownerMessage = [
  'Human handoff requested',
  'Customer: ' + ($json.name || 'unknown') + ' (' + $json.from + ')',
  'Reason: ' + ($json.handoffReason || 'unknown'),
  'Message: ' + $json.text,
  'Reply on WhatsApp: https://wa.me/' + $json.from,
].join('\n');
return { json: { ...$json, reply, kind: 'handoff', handoff: true, ownerMessage } };

// Finalize Reply
// Every path (bot answer, handoff, unsupported) ends here. Clean up the text
// for WhatsApp and build the exact fields the "Send WhatsApp Reply" node needs.
let reply = String($json.reply || '').trim();
reply = reply
  .replace(/\*\*(.+?)\*\*/g, '*$1*') // Markdown bold -> WhatsApp bold
  .replace(/^#{1,6}\s+/gm, '') // Markdown headings are not rendered
  .slice(0, 4000); // WhatsApp text limit is 4096 characters
if (!reply) reply = 'Sorry, something went wrong. Please try again in a moment.';

return {
  json: {
    to: $json.from,
    reply,
    kind: $json.kind || 'bot',
    handoff: Boolean($json.handoff),
    handoffReason: $json.handoffReason || null,
    from: $json.from,
    name: $json.name || null,
    text: $json.text || '',
    messageId: $json.messageId || null,
    lang: $json.lang || null,
    model: $json.model || null,
    tokens: $json.tokens || null,
  },
};

// Update Memory
// Store this exchange so the next message from the same number has context.
// Keeps 40 messages per number and the 500 most recently active numbers.
const ctx = $('Finalize Reply').item.json;
const store = $getWorkflowStaticData('global');
store.memory = store.memory || {};
const now = Date.now();

if (ctx.kind === 'bot' || ctx.kind === 'handoff') {
  const list = store.memory[ctx.to] || [];
  list.push({ role: 'user', content: ctx.text, ts: now });
  list.push({ role: 'assistant', content: ctx.reply, ts: now });
  store.memory[ctx.to] = list.slice(-40);
}

const numbers = Object.keys(store.memory);
if (numbers.length > 500) {
  const last = (n) => store.memory[n][store.memory[n].length - 1].ts;
  numbers.sort((a, b) => last(a) - last(b));
  for (const n of numbers.slice(0, numbers.length - 500)) delete store.memory[n];
}
return { json: ctx };

// Log Exchange
// Appends one entry per exchange to workflow static data (last 200 kept).
// Inspect it from a Code node with $getWorkflowStaticData('global').log, or
// enable the Google Sheets node after this one for a permanent log.
const ctx = $('Finalize Reply').item.json;
const store = $getWorkflowStaticData('global');
store.log = store.log || [];

const entry = {
  timestamp: new Date().toISOString(),
  from: ctx.from,
  name: ctx.name,
  messageId: ctx.messageId,
  inbound: ctx.text,
  reply: ctx.reply,
  kind: ctx.kind,
  handoffReason: ctx.handoffReason,
  model: ctx.model,
  tokens: ctx.tokens,
  dryRun: $env.WA_DRY_RUN === 'true',
};
store.log.push(entry);
if (store.log.length > 200) store.log = store.log.slice(-200);
return { json: entry };
